/// Provenance headers for generated state files (spec 1126, order 5).
///
/// Every state file the plugin freshly emits is stamped with a
/// `// GENERATED BY zuraffa zfa state create — DO NOT EDIT BY HAND.`
/// header plus the generator version and a regeneration hint, mirroring
/// the datasource (spec #1131 order 5) and provider (spec #979)
/// conventions. The header lets `zfa proof check`-style provenance
/// audits and humans distinguish generated state classes from
/// hand-written ones, and names the exact command that reproduces the
/// artifact.
///
/// The header is deliberately DETERMINISTIC: it carries the generator
/// VERSION but never a wall-clock timestamp. The state surface has two
/// byte-identity gates (the snapshot goldens and the
/// `zfa state create` ≡ `zfa make --state` drift gate) that compare
/// emissions across runs and entry points — run-varying header bytes
/// would permanently break them. The run timestamp provenance lives in
/// the receipt's `at` field instead (machine-readable, sha256-bound).
library;

import '../../version.dart';

/// The provenance header factory for the state plugin.
abstract final class StateProvenance {
  /// The provenance marker line stamped on every freshly emitted state
  /// file (spec 1126 order 5).
  static const String generatedHeader =
      '// GENERATED BY zuraffa zfa state create — DO NOT EDIT BY HAND.';

  /// The full header block (marker + version + regeneration hint) for
  /// one emitted file. [entityName] is the PascalCase entity the file
  /// was generated for.
  static String headerFor(String entityName) =>
      '$generatedHeader\n'
      '// Generator version: $version. Regenerate with: '
      'zfa state create --name $entityName (--force to overwrite).\n\n';
}
